local IngotSmelter = {}
local PRODUCTS = {
    iron_ingot = { name = "Železen ingot", ironOreCost = 3, fuelCost = 2, time = 3, cost = 25, purity = 60, description = "Železen ingot iz rude." },
    copper_ingot = { name = "Bakren ingot", copperOreCost = 3, fuelCost = 2, time = 4, cost = 50, purity = 70, prestige = 1, description = "Bakren ingot iz rude." },
    bronze_ingot = { name = "Bronast ingot", copperOreCost = 3, tinOreCost = 1, fuelCost = 2, time = 5, cost = 110, purity = 80, prestige = 2, happiness = 1, description = "Bronast ingot iz zlitine bakra in kositra." },
    brass_ingot = { name = "Medeninast ingot", copperOreCost = 3, zincOreCost = 1, fuelCost = 2, time = 6, cost = 220, purity = 85, prestige = 4, happiness = 2, description = "Medeninast ingot iz zlitine bakra in cinka." },
    silver_refined_ingot = { name = "Rafiniran srebrni ingot", silverOreCost = 3, leadCost = 1, fuelCost = 2, time = 9, cost = 480, purity = 92, prestige = 9, happiness = 3, description = "Rafiniran srebrni ingot za plemiče." },
    royal_grand_ingot = { name = "Kraljevski veliki ingot", goldOreCost = 3, silverOreCost = 2, jewelCost = 1, fuelCost = 3, time = 14, cost = 1800, purity = 100, prestige = 35, happiness = 8, description = "Veliki kraljevski ingot z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Kovinska livarna", cost = { gold = 350, wood = 140, stone = 250 }, upkeep = 9, qualityBonus = 5 },
    blast_furnace = { name = "Visoka peč", cost = { gold = 1200, wood = 300, stone = 550, iron = 10 }, upkeep = 30, qualityBonus = 18 },
    refining_furnace = { name = "Rafinerijska peč", cost = { gold = 2800, wood = 400, stone = 850, silver = 50, fuel = 10 }, upkeep = 70, qualityBonus = 30 },
    royal_smelter_atelier = { name = "Kraljevski atelje kovin", cost = { gold = 11000, wood = 600, stone = 1200, gold = 80, jewel = 25 }, upkeep = 220, qualityBonus = 55, prestigeBonus = 45 },
}
IngotSmelter.ironOreStock = 22; IngotSmelter.copperOreStock = 20; IngotSmelter.tinOreStock = 14; IngotSmelter.zincOreStock = 12; IngotSmelter.silverOreStock = 12; IngotSmelter.goldOreStock = 10; IngotSmelter.leadStock = 12; IngotSmelter.fuelStock = 18; IngotSmelter.jewelStock = 6
IngotSmelter.productStock = {}; IngotSmelter.buildings = {}; IngotSmelter.maker = nil; IngotSmelter.activeMaking = {}; IngotSmelter.totalProducts = 0; IngotSmelter.dayTimer = 0
function IngotSmelter.init() IngotSmelter.ironOreStock=22; IngotSmelter.copperOreStock=20; IngotSmelter.tinOreStock=14; IngotSmelter.zincOreStock=12; IngotSmelter.silverOreStock=12; IngotSmelter.goldOreStock=10; IngotSmelter.leadStock=12; IngotSmelter.fuelStock=18; IngotSmelter.jewelStock=6; IngotSmelter.productStock={}; IngotSmelter.buildings={}; IngotSmelter.maker=nil; IngotSmelter.activeMaking={}; IngotSmelter.totalProducts=0; IngotSmelter.dayTimer=0; print("[IngotSmelter] Royal Ingot Smelter System initialized (6 products, 4 buildings)") end
function IngotSmelter.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; IngotSmelter.maker={name=n or ("Kovinolivar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kovinolivar najet: %s (spretnost: %d)",IngotSmelter.maker.name,s),"success") end; return true end
function IngotSmelter.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function IngotSmelter.build(id) local ok,e=IngotSmelter.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(IngotSmelter.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function IngotSmelter.getQualityBonus() local b=0; for _,bd in ipairs(IngotSmelter.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function IngotSmelter.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironOreCost and IngotSmelter.ironOreStock<(d.ironOreCost or 0) then return false,"Premalo železove rude" end; if d.copperOreCost and IngotSmelter.copperOreStock<(d.copperOreCost or 0) then return false,"Premalo bakrove rude" end; if d.tinOreCost and IngotSmelter.tinOreStock<(d.tinOreCost or 0) then return false,"Premalo kositrne rude" end; if d.zincOreCost and IngotSmelter.zincOreStock<(d.zincOreCost or 0) then return false,"Premalo cinkove rude" end; if d.silverOreCost and IngotSmelter.silverOreStock<(d.silverOreCost or 0) then return false,"Premalo srebrove rude" end; if d.goldOreCost and IngotSmelter.goldOreStock<(d.goldOreCost or 0) then return false,"Premalo zlate rude" end; if d.leadCost and IngotSmelter.leadStock<(d.leadCost or 0) then return false,"Premalo svinca" end; if d.fuelCost and IngotSmelter.fuelStock<(d.fuelCost or 0) then return false,"Premalo goriva" end; if d.jewelCost and IngotSmelter.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #IngotSmelter.buildings==0 then return false,"Potrebna delavnica" end; if not IngotSmelter.maker then return false,"Potreben kovinolivar" end; return true end
function IngotSmelter.make(pt,qty) qty=qty or 5; local ok,e=IngotSmelter.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironOreCost then IngotSmelter.ironOreStock=IngotSmelter.ironOreStock-d.ironOreCost*qty end; if d.copperOreCost then IngotSmelter.copperOreStock=IngotSmelter.copperOreStock-d.copperOreCost*qty end; if d.tinOreCost then IngotSmelter.tinOreStock=IngotSmelter.tinOreStock-d.tinOreCost*qty end; if d.zincOreCost then IngotSmelter.zincOreStock=IngotSmelter.zincOreStock-d.zincOreCost*qty end; if d.silverOreCost then IngotSmelter.silverOreStock=IngotSmelter.silverOreStock-d.silverOreCost*qty end; if d.goldOreCost then IngotSmelter.goldOreStock=IngotSmelter.goldOreStock-d.goldOreCost*qty end; if d.leadCost then IngotSmelter.leadStock=IngotSmelter.leadStock-d.leadCost*qty end; if d.fuelCost then IngotSmelter.fuelStock=IngotSmelter.fuelStock-d.fuelCost*qty end; if d.jewelCost then IngotSmelter.jewelStock=IngotSmelter.jewelStock-d.jewelCost*qty end; local t=d.time; if IngotSmelter.maker then t=math.max(1,t-math.floor(IngotSmelter.maker.skill/12)) end; table.insert(IngotSmelter.activeMaking,{id="ingot_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,purity=d.purity or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function IngotSmelter.completeMaking(m) local q=1.0+(IngotSmelter.getQualityBonus()/100); if IngotSmelter.maker then q=q+(IngotSmelter.maker.skill/150) end; q=math.min(2.5,q); IngotSmelter.productStock[m.productType]=(IngotSmelter.productStock[m.productType] or 0)+m.quantity; IngotSmelter.totalProducts=IngotSmelter.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if IngotSmelter.maker then IngotSmelter.maker.itemsMade=IngotSmelter.maker.itemsMade+m.quantity; if math.random()<0.25 then IngotSmelter.maker.skill=math.min(100,IngotSmelter.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ingot izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"ingot.completed",{productName=m.productName,purity=m.purity}) end end
function IngotSmelter.update(dt) if not _G.state then return end; IngotSmelter.dayTimer=IngotSmelter.dayTimer+dt; if IngotSmelter.dayTimer>=30 then IngotSmelter.dayTimer=0; for i=#IngotSmelter.activeMaking,1,-1 do local m=IngotSmelter.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then IngotSmelter.completeMaking(m); table.remove(IngotSmelter.activeMaking,i) end end; local tu=0; for _,bd in ipairs(IngotSmelter.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if IngotSmelter.maker then tu=tu+18 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function IngotSmelter.getStats() return {ironOreStock=IngotSmelter.ironOreStock,copperOreStock=IngotSmelter.copperOreStock,tinOreStock=IngotSmelter.tinOreStock,zincOreStock=IngotSmelter.zincOreStock,silverOreStock=IngotSmelter.silverOreStock,goldOreStock=IngotSmelter.goldOreStock,leadStock=IngotSmelter.leadStock,fuelStock=IngotSmelter.fuelStock,jewelStock=IngotSmelter.jewelStock,productStock=IngotSmelter.productStock,numBuildings=#IngotSmelter.buildings,hasMaker=IngotSmelter.maker~=nil,makerName=IngotSmelter.maker and IngotSmelter.maker.name or "—",makerSkill=IngotSmelter.maker and IngotSmelter.maker.skill or 0,activeMaking=#IngotSmelter.activeMaking,totalProducts=IngotSmelter.totalProducts} end
return IngotSmelter
